import pandas as pd

def run(inputs: dict) -> dict:
    inbound = inputs["inbound"]
    target_snapshot = inputs["target_snapshot"]

    # Step 1: build STG_NEW
    filtered = inbound[inbound["qty"] > 0]

    if filtered.empty:
        stg_new = pd.DataFrame(
            columns=["product_id", "batch_date", "total_qty", "max_unit_cost"]
        )
    else:
        grouped = (
            filtered.groupby(["product_id", "batch_date"], as_index=False)
            .agg(
                total_qty=("qty", "sum"),
                max_unit_cost=("unit_cost", "max"),
            )
        )
        stg_new = grouped[["product_id", "batch_date", "total_qty", "max_unit_cost"]]

    # Step 2: DELETE FROM TARGET_SNAPSHOT WHERE batch_date IN (distinct batch_date of STG_NEW)
    arriving_dates = set(stg_new["batch_date"].unique())

    if len(arriving_dates) == 0:
        remaining = target_snapshot.copy()
    else:
        remaining = target_snapshot[~target_snapshot["batch_date"].isin(arriving_dates)].copy()

    # Step 3: INSERT INTO TARGET_SNAPSHOT SELECT * FROM STG_NEW
    result = pd.concat([remaining, stg_new], ignore_index=True)

    # Ensure column order matches target
    result = result[["product_id", "batch_date", "total_qty", "max_unit_cost"]]

    return {"target_snapshot": result}
